mapper.select:
SELECT *
FROM ticket_order
WHERE user_id = #{userId}
AND client_request_id = #{clientRequestId}
LIMIT 1

SELECT * FROM passenger WHERE user_id = #{userId} AND id IN
#{passengerId}
ORDER BY id FOR UPDATE

SELECT orders.id AS order_id, orders.order_no, orders.status, orders.total_amount, orders.expire_at, orders.created_at, MIN(run.run_date) AS first_travel_date, GROUP_CONCAT(DISTINCT train.train_no ORDER BY TIMESTAMP(DATE_ADD(run.run_date, INTERVAL from_stop.departure_day_offset DAY), from_stop.departure_time) SEPARATOR '/') AS train_nos, SUBSTRING_INDEX(GROUP_CONCAT(from_station.name ORDER BY TIMESTAMP(DATE_ADD(run.run_date, INTERVAL from_stop.departure_day_offset DAY), from_stop.departure_time) SEPARATOR ','), ',', 1) AS from_station_name, SUBSTRING_INDEX(GROUP_CONCAT(to_station.name ORDER BY TIMESTAMP(DATE_ADD(run.run_date, INTERVAL to_stop.arrival_day_offset DAY), to_stop.arrival_time) DESC SEPARATOR ','), ',', 1) AS to_station_name, COUNT(DISTINCT item.passenger_id) AS passenger_count, COUNT(item.id) AS ticket_count FROM ticket_order orders JOIN order_item item ON item.order_id = orders.id JOIN train_run run ON run.id = item.run_id JOIN train ON train.id = run.train_id JOIN train_stop from_stop ON from_stop.train_id = run.train_id AND from_stop.stop_seq = item.from_seq JOIN train_stop to_stop ON to_stop.train_id = run.train_id AND to_stop.stop_seq = item.to_seq JOIN station from_station ON from_station.id = item.from_station_id JOIN station to_station ON to_station.id = item.to_station_id WHERE orders.user_id = #{userId}
AND orders.status = #{status}
AND orders.created_at >= #{orderDateFrom}
AND orders.created_at < DATE_ADD(#{orderDateTo}, INTERVAL 1 DAY)
AND EXISTS ( SELECT 1 FROM order_item date_item JOIN train_run date_run ON date_run.id = date_item.run_id WHERE date_item.order_id = orders.id
AND date_run.run_date >= #{travelDateFrom}
AND date_run.run_date <= #{travelDateTo}
)
AND (orders.order_no LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM order_item keyword_item JOIN passenger keyword_passenger ON keyword_passenger.id = keyword_item.passenger_id JOIN train_run keyword_run ON keyword_run.id = keyword_item.run_id JOIN train keyword_train ON keyword_train.id = keyword_run.train_id JOIN station keyword_from_station ON keyword_from_station.id = keyword_item.from_station_id JOIN station keyword_to_station ON keyword_to_station.id = keyword_item.to_station_id WHERE keyword_item.order_id = orders.id AND ( keyword_train.train_no LIKE CONCAT('%', #{keyword}, '%') OR keyword_from_station.name LIKE CONCAT('%', #{keyword}, '%') OR keyword_to_station.name LIKE CONCAT('%', #{keyword}, '%') OR keyword_passenger.name LIKE CONCAT('%', #{keyword}, '%') ) ) )
GROUP BY orders.id, orders.order_no, orders.status, orders.total_amount, orders.expire_at, orders.created_at ORDER BY orders.created_at DESC, orders.id DESC

